**3. Resolve live repo state before any push**  
- Query GitHub API `GET /repos/Vondada/chey-app` to get `default_branch`.  
- Verify the ref exists: `GET /repos/Vondada/chey-app/git/refs/heads/${default_branch}`.  
- If the call returns 404 (or “base branch not found”), repeat the metadata request, then:
  * Refresh the repo cache.
  * Confirm `refs/heads/main` exists.
  * Use the SHA from that ref as the base for the new repair branch.

**4. Create/checkout repair branch**  
```js
async function ensureBaseBranch() {
  const repoInfo = await github.getRepo('Vondada', 'chey-app');
  let base = repoInfo.default_branch || 'main';

  let ref;
  try {
    ref = await github.getRef(`heads/${base}`);
  } catch (e) {
    // base branch missing – refresh and fallback to main
    await github.refreshRepoCache('Vondada', 'chey-app');
    ref = await github.getRef('heads/main');
    base = 'main';
  }
  return { base, sha: ref.object.sha };
}
```

**5. Create repair branch and push**  
```js
async function pushRepair(change) {
  const { base, sha } = await ensureBaseBranch();
  const repairBranch = `repair/${Date.now()}`;
  await github.createBranch('Vondada', 'chey-app', repairBranch, sha);
  // apply change, commit, and push to repairBranch
}
```

